const fs=require('node:fs');const path='actualites/index.json';const data=JSON.parse(fs.readFileSync(path,'utf8'));const before=data.articles.length;data.articles=data.articles.filter(article=>{if(!article.path)return true;if(article.status==='deleted')return false;const normalized=article.path.replaceAll('\\','/');if(!/^actualites\/[A-Za-z0-9_-]+\/contenu\.json$/.test(normalized))return true;return fs.existsSync(normalized)});if(data.articles.length!==before){data.updatedAt=new Date().toISOString();fs.writeFileSync(path,JSON.stringify(data,null,2)+'\n');console.log('Removed '+(before-data.articles.length)+' deleted publications from index')}else console.log('Index already synchronized');